    {
      "id": "6",
      "type": "SIDE",
      "text": "Writes the first uVar6 elements of the input string to out.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "7",
      "type": "IO",
      "text": "Returns uVar6 << 0x20 | uVar7 when uVar6 is less than or equal to param_5 and uVar6 is not 0.",
      "asserted_values": [],
