    }
  ],
  "recovered_c": "uint64_t fn_17(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  uint64_t uVar1;\n  uint8_t *puVar2;\n  uint8_t *puVar3;\n  size_t lVar4;\n  uint64_t uVar5;\n  uint64_t uVar6;\n  uint64_t uVar7;\n\n  uVar7 = 0;\n  uVar6 = 0;\n  uVar1 = 0;\n  if (len == 0) {\n    return 0;\n  }\n  do {\n    if (in[uVar1] == '\\0') break;\n    if (len < uVar1 + 2) {\n      return 0xffffffffffffffff;\n    }\n    uVar5 = (uint64_t)in[1 + uVar1];\n    uVar1 = uVar1 + 2 + uVar5;\n    if (len < uVar1) {\n      return 0xffffffffffffffff;\n    }\n    uVar7 = uVar7 + uVar5;\n    uVar6 = uVar6 + 1;\n  } while (uVar1 < len);\n  uint64_t uVar1 = 0xffffffffffffffff;\n  if ((uVar6 <= out_cap) && (uVar1 = uVar6 << 0x20 | uVar7, uVar6 != 0)) {\n    lVar4 = 0;\n    puVar2 = out;\n    do {\n      puVar3 = puVar2 + 1;\n      *puVar2 = in[lVar4];\n      lVar4 = (uint64_t)in[1 + lVar4] + 2 + lVar4;\n      puVar2 = puVar3;\n    } while (puVar3 != out + uVar6);\n    return uVar1;\n  }\n  return uVar1;\n}"
